#!/usr/bin/env python3
"""Render the complete publication candidate entirely from the cold derived files."""
import argparse
import json
import pathlib
import audit

HERE=pathlib.Path(__file__).resolve().parent

def render(s,d):
    checked=audit.analyse(d)
    audit.need(all(s[k]==v for k,v in checked.items()),'derived summary differs from evidence')
    t=s['totals'];c=s['coverage'];first,last=s['buys'][0],s['buys'][-1]
    lines=['# Q35: FLAPJAX buyback audit, October 9 through 18, 2026','',
    f"{t['buys']} treasury-funded buys spent {t['BNB']} BNB-equivalent of WBNB and delivered {t['FLAPJAX']} FLAPJAX to the treasury. The daily-cadence statement mismatches UTC dates: October 15 and 16 have no buy, and October 17 has two. UTC-5 and UTC-4 calendar dates each give one buy per day except October 15.",'',
    'This independently recomputed answer addresses [Taskmarket TSK-88YN3100](https://api.taskmarket.dev/api/tasks/0x1284d01695bfcd1720cfb319f658a258b82b6768501fc00cb9ab0748bc45fd35) and its [Q35 specification](https://thecolony.ai/post/254bb713-2201-4ac4-9920-af56d11cc28e). It uses no trade, signature or wallet access.','',
    '## Identities, dates and scope','',
    f"Network: BNB Smart Chain, chain ID 56, independently read from both RPC routes. FLAPJAX: `{audit.FJ}` (`FlapJax`, `FLAPJAX`, 18 decimals). WBNB: `{audit.WBNB}` (`Wrapped BNB`, `WBNB`, 18 decimals). Native BNB also uses 18 decimals.",'',
    f"Named pool: `{audit.POOL}`. On-chain token0 is FLAPJAX, token1 is WBNB, fee is 10000 / 1000000 = 1%, and factory is `{s['metadata']['factory']}`. The factory's `getPool(FLAPJAX,WBNB,10000)` returns this pool. These reads are pinned to block {s['metadata']['block']}; the factory and router agree with [PancakeSwap's official deployments](https://developer.pancakeswap.finance/contracts/v3/addresses).",'',
    f"Treasury: `{audit.TREASURY}`. Every listed buy's transaction signer is this treasury and its destination is router `{first['router']}`. I identify buybacks as successful treasury-signed swaps in the named pool with FLAPJAX leaving it and WBNB entering it. The data establish these public-address flows; they do not establish intent or the operator behind an unrelated address.",'',
    f"Primary calendar: [{audit.START}, {audit.END}), including all of October 9 through 18 UTC. Exact inclusive blocks: {s['window']['firstBlock']} through {s['window']['lastBlock']}. For each time boundary, the saved header immediately before it has an earlier timestamp and the first included header has a timestamp at or after it, with matching parent/hash linkage.",'',
    f"The specification does not name a calendar zone. I also scanned [{d['boundaries']['2026-10-08T10:00:00Z']}, {d['boundaries']['2026-10-19T12:00:00Z']-1}], corresponding to 2026-10-08 10:00Z through just before 2026-10-19 12:00Z. This padding covers all civil UTC offsets from -12 through +14. The UTC-5 and UTC-4 ten-day windows have the same nine buy hashes and zero treasury-to-named-pool token transfers. Other arbitrary calendar zones can select different boundary buys, so UTC remains the headline interpretation.",'',
    f"Observation: node-reported finalized block {int(s['finalized']['number'],16)}, hash `{s['finalized']['hash']}`, timestamp {audit.iso(int(s['finalized']['timestamp'],16))}. This is {int(s['finalized']['number'],16)-s['window']['lastBlock']} blocks beyond the UTC window's last block. Capture finished {d['capturedAt']}; evidence enrichment added only public identity/event-hash calls.",'',
    '## Every buy, exact amounts','',
    'BNB input below is the WBNB credit to the pool, also equal to the positive token1 amount in the Swap event. FLAPJAX is the exact token Transfer amount, never a rounded marketing number. All recipients are spelled out.','',
    '| # | UTC | Transaction | Block | BNB input | FLAPJAX received | Recipient |',
    '| --- | --- | --- | --- | --- | --- | --- |']
    for i,b in enumerate(s['buys'],1):
        lines.append(f"| {i} | {b['UTC']} | [{b['tx']}](https://bscscan.com/tx/{b['tx']}) | [{b['block']}](https://bscscan.com/block/{b['block']}) | {b['BNB_input']} | {b['FLAPJAX']} | `{b['recipient']}` |")
    lines += ['', 'Block identities and token Transfer log indexes:', '', '| Block | Block hash | Transfer log index | Swap log index |', '| --- | --- | --- | --- |']
    for b in s['buys']:lines.append(f"| {b['block']} | `{b['blockHash']}` | {b['transferLogIndex']} | {b['swapLogIndex']} |")
    lines += ['', '## Totals and price formulas','',
    f"Sum of pool inputs = {t['WBNB_atoms']} WBNB atoms / 10^18 = **{t['BNB']} BNB-equivalent**. Each of the {t['buys']} discovered buys supplies 10000000000000000 atoms = 0.01. Sum of actual token outputs = {t['FJ_atoms']} FLAPJAX atoms / 10^18 = **{t['FLAPJAX']} FLAPJAX**.",'',
    'For buy i, let b_i be its input atoms and f_i its FLAPJAX Transfer atoms. With both decimals equal to 18, price_i = (b_i / 10^18) / (f_i / 10^18) = b_i / f_i BNB per FLAPJAX. Weighted average = sum(b_i) / sum(f_i), equivalently weighting each price_i by its received FLAPJAX. This is not the arithmetic mean of the nine per-buy prices.','',
    f"- Weighted average: {t['WBNB_atoms']} / {t['FJ_atoms']} = **{t['weightedPrice']['BNB_per_FLAPJAX']} BNB/FLAPJAX**.",
    f"- First buy: {first['WBNB_input_atoms']} / {first['FJ_atoms']} = **{t['firstPrice']['BNB_per_FLAPJAX']} BNB/FLAPJAX**.",
    f"- Last buy: {last['WBNB_input_atoms']} / {last['FJ_atoms']} = **{t['lastPrice']['BNB_per_FLAPJAX']} BNB/FLAPJAX**.",'',
    f"These displayed prices are rounded; the integer ratios are exact. Price includes the input paid to the pool, including its swap fee, and excludes transaction gas. The nine transactions have native `value` totaling {audit.units(int(t['native_value_atoms']))} BNB, separately observed WBNB inputs totaling {t['BNB']}, and `gasUsed * effectiveGasPrice` totaling {t['gas_atoms']} wei = {t['gas_BNB']} BNB. Value plus gas is {t['value_plus_gas_BNB']} BNB.",'',
    'For each buy, treasury native balance at the previous block minus its balance at the buy block equals tx.value plus gas: the saved block-scoped net residual is zero. This is a balance reconciliation, not an internal-call trace or proof that no internal refund path executed. Native value, WBNB received by the pool, gas, and possible internal refunds are distinct concepts; the reported execution price uses the verified WBNB pool input.','',
    '## Statement verdicts','',
    '| Statement | Verdict | Chain basis |', '| --- | --- | --- |',
    '| Nine buys, each 0.01 BNB, totaling 0.09 BNB | MATCH | Nine independently discovered treasury-signed buys; every Swap/input Transfer is 10000000000000000 WBNB atoms; all native transaction values also equal 0.01 BNB. |',
    '| One per day except October 15 | MISMATCH in UTC; MATCH in UTC-5 and UTC-4 | UTC has zero on October 15 and 16 and two on October 17. The 02:00:51Z buy at block 128086717 is October 16 21:00:51 in UTC-5 and October 16 22:00:51 in UTC-4. No operational time zone is asserted from that fact. |',
    '| Every buy\'s FLAPJAX went to the treasury | MATCH | Every listed token Transfer is pool to treasury and equals the negative token0 Swap amount. Output recipients were checked after discovery rather than used to prefilter the buy list. |',
    f"| Treasury sent no FLAPJAX to the named pool in the window | MATCH under the returned complete-range logs | All {c['windowTokenTransfers']} token Transfer logs were examined, including all {c['windowTreasuryOutflows']} treasury outflows; zero have treasury as from and the named pool as to. This test is independent of the nine buy receipts. |",
    '| Missed buy is owed as a make-up on October 23 | UNKNOWN as an on-chain outcome | October 23 is future at the October 20 capture. The statement is a promise; this audit proves no future buy, enforceable debt, or eventual fulfillment. |','',
    '| Calendar date | UTC buys | UTC-5 buys | UTC-4 buys |','| --- | --- | --- | --- |']
    for day,count in s['calendarCounts']['UTC'].items():lines.append(f"| {day} | {count} | {s['calendarCounts']['UTC-5'][day]} | {s['calendarCounts']['UTC-4'][day]} |")
    lines += ['', '## Discovery, full coverage and limits','',
    f"The archive source is [NodeReal's documented public, shareable API](https://docs.nodereal.io/reference/getting-started-with-your-api). No private key, account, personal API credential or paid plan is used. Endpoint: `{d['primary']}`. [BNB Chain documents that its own public endpoints disable eth_getLogs](https://docs.bnbchain.org/bnb-smart-chain/developers/json_rpc/json-rpc-endpoint/); that failure is not interpreted as zero activity.",'',
    f"I queried every FLAPJAX Transfer and every event issued by the named pool across padded blocks {c['firstPaddedBlock']} through {c['lastPaddedBlock']}, inclusive. Each issuer has {c['coarseRanges']} consecutive 50000-block-or-smaller requests and a separate {c['fineRanges']} consecutive 25000-block-or-smaller partition. The two partitions return identical log identities and contents: {c['paddedTokenTransfers']} token Transfers and {c['paddedPoolEvents']} pool events, all {c['paddedSwaps']} of them swaps. Every response, exact from/to range and empty result is retained in `evidence/rpc.jsonl`; there is no cursor pagination or unqueried range. The maximum actual log count per response is {max(r[2] for scan in d['scans'].values() for part in scan.values() for r in part['ranges'])}, safely below the client refusal threshold of 1000. That threshold is a conservative guard, not a claimed provider limit.",'',
    f"Inside the UTC window there are {c['windowSwaps']} swaps. {t['buys']} are the listed treasury buys; the other {c['windowOtherSwaps']} are {c['windowOtherBuys']} buys and {c['windowOtherSells']} sells by other signers. The token has {c['windowPoolOutflows']} pool-to-recipient transfers in that window: {c['windowPoolToTreasury']} to the treasury and {c['windowPoolOutflows']-c['windowPoolToTreasury']} to others. The padded interval additionally includes treasury buys on October 8 18:38:46Z and October 19 09:28:47Z; both are excluded from UTC, UTC-5 and UTC-4 headline totals.",'',
    'PancakeSwap V3 Swap is `Swap(address,address,int256,int256,uint160,uint128,int24,uint128,uint128)`. Its topic is `'+audit.SWAP+'`, confirmed by a saved `web3_sha3` call and the [official event interface](https://github.com/pancakeswap/pancake-v3-contracts/blob/'+json.loads((HERE/'evidence/pool-events-source.json').read_text())['commit']+'/projects/v3-core/contracts/interfaces/pool/IPancakeV3PoolEvents.sol). The first two data words are signed pool deltas: negative FLAPJAX, positive WBNB means buying FLAPJAX. The token Transfer topic is `'+audit.TRANSFER+'`; topics[1]/[2] are from/to and data is uint256. The issuer address is checked for every log.','',
    f"All {c['paddedSwaps']} swap transactions, their complete receipts, and block headers were read again from the independent public route `{d['secondary']}`. Decisive transaction fields, status, block hash/time and every receipt log agree. Range coverage uses one archive provider under two partitions; the second route does not supply a second full-range archive scan. An identically incomplete or dishonest archive response could evade the partition check. This is reproducible RPC evidence with that trust boundary, not a consensus/receipt-trie proof of absence. The no-send verdict concerns this token, treasury and named pool, not every pool or indirect route on BSC.",'',
    '## Reproduce','',
    'With the accompanying files, no install or live RPC is needed for cold recomputation:', '', '```sh', 'python3 verify.py', 'python3 audit.py --evidence evidence --out replayed', 'node cold-independent.mjs evidence replayed', 'python3 render.py --evidence evidence --derived replayed --out replayed/PUBLIC-AUDIT.md', 'python3 verify.py --replayed replayed', 'python3 -m unittest discover -s . -p test_audit.py -v', '```','',
    'The Python replay validates complete coverage and joins every input to the saved RPC journal. The separate JavaScript BigInt replay discovers buys from token outflows and uses the second provider\'s receipts; it independently agrees on every row, exact sum, first/last/weighted ratio, and treasury-outflow count. `derived/buys.csv` and `derived/summary.json` retain the exact values. `SHA256SUMS` identifies the frozen delivery bytes.','',
    'The delivered replay uses only the saved public RPC journal and ordinary Python/Node standard libraries. It reconstructs the aggregate capture in memory, so no duplicate raw evidence file or collector is needed. Every historic query, scope and response is retained for independent inspection. Current live provider availability can differ.','',
    'A single buy can also be checked on any public BSC node:', '', '```sh', 'curl -s https://bsc-dataseed.bnbchain.org -H "content-type: application/json" --data \'{"jsonrpc":"2.0","id":1,"method":"eth_getTransactionReceipt","params":["'+first['tx']+'"]}\'', '```','',
    f"Keep the log issued by `{audit.FJ}` with Transfer topic and index {first['transferLogIndex']}. Its from/to are the named pool and treasury, and its data converts to {first['FJ_atoms']} atoms. `eth_getTransactionByHash` supplies value; `eth_getBlockByNumber` for block {first['block']} supplies timestamp/hash. The full working and range queries are included so the receipt table and negative transfer test can both be rechecked.",'']
    return '\n'.join(lines)

def main():
    p=argparse.ArgumentParser();p.add_argument('--derived',type=pathlib.Path,default=HERE/'derived');p.add_argument('--evidence',type=pathlib.Path,default=HERE/'evidence');p.add_argument('--out',type=pathlib.Path,default=HERE/'PUBLIC-AUDIT.md');a=p.parse_args()
    s=json.loads((a.derived/'summary.json').read_text());d=audit.load_capture(a.evidence/'rpc.jsonl');a.out.write_text(render(s,d))
if __name__=='__main__':main()
